/* First-dose visibility without a second clinical record or a new primary menu. */
(()=>{let mode='all',observedServer='',offset=0;const n=x=>x===null?'—':x.toFixed(1),safe=x=>esc(encodeURIComponent(x||'').replace(/'/g,'%27'));const time=x=>x?fmt(x):'Unknown';
function now(){if(teamData?.serverTime&&teamData.serverTime!==observedServer){observedServer=teamData.serverTime;offset=Date.parse(observedServer)-Date.now()}return Date.now()+(Number.isFinite(offset)?offset:0)}
function data(){return FNTTACore.build(teamSession?.signedIn?teamData?.visits||[]:[],now())}
function quality(r){return({met:'Appropriate dose within 60 min',late:'Appropriate dose after 60 min',missing_time:'Triage / administration time missing',appropriateness_unknown:'Appropriateness review pending',not_appropriate:'Regimen reviewed as inappropriate',eligibility_unknown:'Eligibility review pending',excluded:'Excluded by review',not_eligible:'Not eligible'})[r.outcome||r.group]||'Review needed'}
function status(r){if(r.clock==='excluded')return 'Excluded / not eligible';if(r.doseId)return r.doseMinutes===null?'Dose documented · timing unavailable':`${r.doseMinutes>60?'Dose late':'Dose within 60 min'} · ${n(r.doseMinutes)} min`;if(r.remaining===null)return 'Triage time missing';return r.remaining<0?`${n(-r.remaining)} min overdue`:`${n(r.remaining)} min remaining`}
function teamCard(inDashboard=false){const loaded=!!teamSession?.signedIn&&!!teamData,m=data();return `<section class="tta-hero" aria-label="Time-to-antibiotic overview"><div class="tta-hero-head"><div><span>FIRST-DOSE CONTROL</span><h2>${inDashboard?'First-dose overview':'Time to antibiotic'}</h2><p>${loaded?'Live overview of loaded shared encounters · first-dose target ≤60 minutes from triage.':'Connect your shared workspace to see real documented encounter times.'}</p></div>${inDashboard?'<button class="btn" onclick="go(\'Team workspace\')">Team workspace</button>':'<button class="btn primary" onclick="FNTTA.open()">Open time-to-antibiotic dashboard</button>'}</div><div class="tta-summary">${[['Awaiting first dose',loaded?m.waiting:'—','waiting'],['Due in ≤15 min',loaded?m.dueSoon:'—','due'],['Overdue',loaded?m.overdue:'—','overdue'],['Appropriate dose ≤60 min',loaded&&m.summary.percent!==null?m.summary.percent.toFixed(1)+'%':'—','all']].map(([label,value,key])=>`<button class="tta-stat ${key}" onclick="FNTTA.open('${key}')"><span>${label}</span><strong>${value}</strong></button>`).join('')}</div><p class="tta-foot">${loaded?`${m.missingTriage} missing triage times · ${m.reviewNeeded} documented doses awaiting appropriateness review · ${m.summary.numerator}/${m.summary.denominator} reviewed eligible encounters`:'No data is shown as zero performance. Device rehearsal is separate from shared work.'}</p></section>`}
function dashboard(){const loaded=!!teamSession?.signedIn&&!!teamData,m=data(),rows=FNTTACore.filter(m.rows,mode);return header('Time-to-antibiotic dashboard','Triage → actual first dose. One encounter, one documented timeline.',`<div class="actions"><button class="btn" onclick="FNTTA.refresh()">Refresh shared data</button><button class="btn" onclick="FNEncounterUI.export()">Export measures</button></div>`)+(!loaded?`<section class="panel"><h2>Load shared encounters</h2><p>Sign in and load your team to view first-dose performance. Device-local records do not populate this dashboard.</p><button class="btn primary" onclick="FNTTA.refresh()">Load my shared workspace</button>${teamError?`<p class="notice">${esc(teamError)}</p>`:''}</section>`:teamCard(true)+`<div class="tta-quality"><div><small>TRIAGE → DOSE · MEDIAN</small><b>${n(m.summary.dose.median)} min</b><span>P90 ${n(m.summary.dose.p90)} min · ${m.summary.dose.n} timed eligible encounters</span></div><div><small>MEASUREMENT QUALITY</small><b>${m.summary.unknown} unresolved</b><span>${m.summary.excluded} excluded · ${m.summary.notEligible} not eligible</span></div></div><section class="panel"><div class="sectiontitle"><div><h2>First-dose priority queue</h2><p>Overdue encounters appear first. Open the same visit to act or correct missing evidence.</p></div><label class="field">Show<select aria-label="First-dose queue filter" onchange="FNTTA.filter(this.value)">${[['all','All encounters'],['overdue','Overdue'],['due','Due in ≤15 minutes'],['waiting','Awaiting dose'],['dosed','Dose documented'],['gaps','Documentation gaps']].map(([k,l])=>`<option value="${k}" ${mode===k?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="scroll"><table class="tta-table"><thead><tr><th>Patient / encounter</th><th>Triage</th><th>First-dose status</th><th>Next step</th><th>Quality result</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.label)}</b><div class="mini">${esc(r.patientId)} · ${esc(r.visitId.slice(0,8))}</div></td><td>${time(r.triageAt)}</td><td><span class="tta-status ${r.clock==='overdue'||r.doseMinutes>60?'late':r.clock==='due_soon'?'soon':r.doseId?'done':''}">${esc(status(r))}</span>${r.doseAt?`<div class="mini">${time(r.doseAt)}</div>`:''}</td><td>${esc(r.next)}</td><td>${esc(quality(r))}<details><summary>${r.gaps.length} documentation gaps</summary>${r.gaps.map(g=>`<p>${esc(g)}</p>`).join('')||'<p>No listed gaps.</p>'}</details></td><td><button class="btn primary" onclick="fnShell.patient('${safe(r.patientId)}','${safe(r.visitId)}','Care plan')">Open care plan</button></td></tr>`).join('')||'<tr><td colspan="6">No loaded encounters match this filter.</td></tr>'}</tbody></table></div></section><details class="tta-method"><summary>Metric definitions, handoff delays & reporting scope</summary><p>Numerator: reviewed eligible adult FN encounters with a documented appropriate first dose ≤60 minutes after triage. Known eligible encounters with missing dose/review data stay in the denominator. Unresolved eligibility and reviewed exclusions are shown separately. A dose timestamp stops the clock but does not by itself establish appropriateness.</p><p>Only the latest loaded 100 shared visits are included. Synthetic training data; no hospital-wide improvement is claimed. The queue refreshes while this page is open. Missing timestamps stay unknown.</p><table><thead><tr><th>Interval</th><th>Median min</th><th>P90 min</th><th>Valid pairs</th></tr></thead><tbody>${m.summary.handoffs.map((h,i)=>`<tr><td>${['Triage → order','Order → pharmacy review','Pharmacy review → drug ready','Drug ready → first dose'][i]}</td><td>${n(h.median)}</td><td>${n(h.p90)}</td><td>${h.n}</td></tr>`).join('')}<tr><td>Result available → review</td><td>${n(m.summary.resultReview.median)}</td><td>${n(m.summary.resultReview.p90)}</td><td>${m.summary.resultReview.n}</td></tr><tr><td>Result available → decision</td><td>${n(m.summary.resultDecision.median)}</td><td>${n(m.summary.resultDecision.p90)}</td><td>${m.summary.resultDecision.n}</td></tr></tbody></table></details>`)}
window.FNTTA={teamCard,dashboard,open(v='all'){mode=v;go('Clinical quality');if(!teamData)refreshTeamWorkspace().then(()=>render())},filter(v){mode=v;render()},async refresh(){await refreshTeamWorkspace();render()}};
const original=FNEncounterUI.panel;FNEncounterUI.panel=function(d){return original(d).replace('<h2>First-hour care & handoffs</h2>','<h2>Time to antibiotic · first-hour care</h2>').replace('<span>60-minute first-dose target</span>','<span>Triage → actual first dose · target ≤60 min</span>')+`<div class="tta-patient-link"><button class="btn" onclick="FNTTA.open()">Open shared time-to-antibiotic dashboard</button><p>Shared dashboard includes shared encounters only. This patient panel retains its displayed shared or device scope.</p></div>`};
// Refresh the read-only overview without replacing an active form.
setInterval(()=>{if(!document.hidden&&['Team workspace','Clinical quality'].includes(view)&&!document.querySelector('#workflowDialog')&&!teamEditing)render()},10000);
})();
